import{_ as p,a0 as r,w as o,s as d,I as s,x as i,a1 as n,A as e,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"初步了解 Git | LCTT x X-CMD","titleTemplate":false,"description":"初步了解 Git | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初步了解 Git | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初步了解 Git | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160711 Getting started with Git","title":"初步了解 Git","tag":"201608","desc":""},"relativePath":"201608/20160711 Getting started with Git.md","filePath":"[post].md"}'),g={name:"201608/20160711 Getting started with Git.md"};function b(u,t,h,G,m,f){const a=r("Link");return o(),d("div",null,[t[25]||(t[25]=s("h1",{id:"初步了解-git",tabindex:"-1"},[i("初步了解 Git "),s("a",{class:"header-anchor",href:"#初步了解-git","aria-label":"Permalink to “初步了解 Git”"},"​")],-1)),t[26]||(t[26]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/get_started_lead.jpeg?itok=r22AKc6P",alt:""})],-1)),t[27]||(t[27]=s("p",null,[s("em",null,"图片来源：opensource.com")],-1)),s("p",null,[t[1]||(t[1]=i("在这个系列的",-1)),n(a,{href:"https://linux.cn/article-7639-1.html"},{default:e(()=>[...t[0]||(t[0]=[i("介绍篇",-1)])]),_:1}),t[2]||(t[2]=i("中，我们学习到了谁应该使用 Git，以及 Git 是用来做什么的。今天，我们将学习如何克隆公共 Git 仓库，以及如何提取出独立的文件而不用克隆整个仓库。",-1))]),t[28]||(t[28]=l(`<p>由于 Git 如此流行，因而如果你能够至少熟悉一些基础的 Git 知识也能为你的生活带来很多便捷。如果你可以掌握 Git 基础（你可以的，我发誓！），那么你将能够下载任何你需要的东西，甚至还可能做一些贡献作为回馈。毕竟，那就是开源的精髓所在：你拥有获取你使用的软件代码的权利，拥有和他人分享的自由，以及只要你愿意就可以修改它的权利。只要你熟悉了 Git，它就可以让这一切都变得很容易。</p><p>那么，让我们一起来熟悉 Git 吧。</p><h3 id="读和写" tabindex="-1">读和写 <a class="header-anchor" href="#读和写" aria-label="Permalink to “读和写”">​</a></h3><p>一般来说，有两种方法可以和 Git 仓库交互：你可以从仓库中读取，或者你也能够向仓库中写入。它就像一个文件：有时候你打开一个文档只是为了阅读它，而其它时候你打开文档是因为你需要做些改动。</p><p>本文仅讲解如何从 Git 仓库读取。我们将会在后面的一篇文章中讲解如何向 Git 仓库写回的主题。</p><h3 id="git-还是-github" tabindex="-1">Git 还是 GitHub？ <a class="header-anchor" href="#git-还是-github" aria-label="Permalink to “Git 还是 GitHub？”">​</a></h3><p>一句话澄清：Git 不同于 GitHub（或 GitLab，或 Bitbucket）。Git 是一个命令行程序，所以它就像下面这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git</span></span>
<span class="line"><span>usage: Git [--version] [--help] [-C &lt;path&gt;] </span></span>
<span class="line"><span>  [-p | --paginate | --no-pager] [--bare]</span></span>
<span class="line"><span>  [--Git-dir=&lt;path&gt;] &lt;command&gt; [&lt;args&gt;]</span></span></code></pre></div><p>由于 Git 是开源的，所以就有许多聪明人围绕它构建了基础软件；这些基础软件，包括在他们自己身边，都已经变得非常流行了。</p><p>我的文章系列将首先教你纯粹的 Git 知识，因为一旦你理解了 Git 在做什么，那么你就无需关心正在使用的前端工具是什么了。然而，我的文章系列也将涵盖通过流行的 Git 服务完成每项任务的常用方法，因为那些将可能是你首先会遇到的。</p><h3 id="安装-git" tabindex="-1">安装 Git <a class="header-anchor" href="#安装-git" aria-label="Permalink to “安装 Git”">​</a></h3><p>在 Linux 系统上，你可以从所使用的发行版软件仓库中获取并安装 Git。BSD 用户应当在 Ports 树的 devel 部分查找 Git。</p>`,12)),s("p",null,[t[4]||(t[4]=i("对于闭源的操作系统，请前往其",-1)),n(a,{href:"https://git-scm.com/download"},{default:e(()=>[...t[3]||(t[3]=[i("项目官网",-1)])]),_:1}),t[5]||(t[5]=i("，并根据说明安装。一旦安装后，在 Linux、BSD 和 Mac OS X 上的命令应当没有任何差别。Windows 用户需要调整 Git 命令，从而和 Windows 文件系统相匹配，或者安装 Cygwin 以原生的方式运行 Git，而不受 Windows 文件系统转换问题的羁绊。",-1))]),t[29]||(t[29]=s("h3",{id:"git-下午茶",tabindex:"-1"},[i("Git 下午茶 "),s("a",{class:"header-anchor",href:"#git-下午茶","aria-label":"Permalink to “Git 下午茶”"},"​")],-1)),t[30]||(t[30]=s("p",null,"并非每个人都需要立刻将 Git 加入到我们的日常生活中。有些时候，你和 Git 最多的交互就是访问一个代码库，下载一两个文件，然后就不用它了。以这样的方式看待 Git，它更像是下午茶而非一次正式的宴会。你进行一些礼节性的交谈，获得了需要的信息，然后你就会离开，至少接下来的三个月你不再想这样说话。",-1)),t[31]||(t[31]=s("p",null,"当然，那是可以的。",-1)),t[32]||(t[32]=s("p",null,"一般来说，有两种方法访问 Git：使用命令行，或者使用一种神奇的因特网技术通过 web 浏览器快速轻松地访问。",-1)),s("p",null,[t[7]||(t[7]=i("假设你想要给终端安装一个回收站，因为你已经被 rm 命令毁掉太多次了。你可能听说过 Trashy ，它称自己为「理智的 rm 命令中间人」，也许你想在安装它之前阅读它的文档。幸运的是，",-1)),n(a,{href:"https://gitlab.com/trashy/trashy"},{default:e(()=>[...t[6]||(t[6]=[i("Trashy 公开地托管在 GitLab.com",-1)])]),_:1}),t[8]||(t[8]=i("。",-1))]),t[33]||(t[33]=s("h3",{id:"landgrab",tabindex:"-1"},[i("Landgrab "),s("a",{class:"header-anchor",href:"#landgrab","aria-label":"Permalink to “Landgrab”"},"​")],-1)),t[34]||(t[34]=s("p",null,"我们工作的第一步是对这个 Git 仓库使用 landgrab 排序方法：我们会克隆这个完整的仓库，然后会根据内容排序。由于该仓库是托管在公共的 Git 服务平台上，所以有两种方式来完成工作：使用命令行，或者使用 web 界面。",-1)),s("p",null,[t[10]||(t[10]=i("要想使用 Git 获取整个仓库，就要使用 git clone 命令和 Git 仓库的 URL 作为参数。如果你不清楚正确的 URL 是什么，仓库应该会告诉你的。GitLab 为你提供了 ",-1)),n(a,{href:"https://gitlab.com/trashy/trashy.git"},{default:e(()=>[...t[9]||(t[9]=[i("Trashy",-1)])]),_:1}),t[11]||(t[11]=i(" 仓库的用于拷贝粘贴的 URL。",-1))]),t[35]||(t[35]=l(`<p><img src="https://opensource.com/sites/default/files/1_gitlab-url.jpg" alt=""></p><p>你也许注意到了，在某些服务平台上，会同时提供 SSH 和 HTTPS 链接。只有当你拥有仓库的写权限时，你才可以使用 SSH。否则的话，你必须使用 HTTPS URL。</p><p>一旦你获得了正确的 URL，克隆仓库是非常容易的。就是 git clone 该 URL 即可，以及一个可选的指定要克隆到的目录。默认情况下会将 git 目录克隆到你当前所在的目录；例如，&#39;trashy.git&#39; 将会克隆到你当前位置的 &#39;trashy&#39; 目录。我使用 .clone 扩展名标记那些只读的仓库，而使用 .git 扩展名标记那些我可以读写的仓库，不过这并不是官方要求的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://gitlab.com/trashy/trashy.git trashy.clone</span></span>
<span class="line"><span>Cloning into &#39;trashy.clone&#39;...</span></span>
<span class="line"><span>remote: Counting objects: 142, done.</span></span>
<span class="line"><span>remote: Compressing objects: 100% (91/91), done.</span></span>
<span class="line"><span>remote: Total 142 (delta 70), reused 103 (delta 47)</span></span>
<span class="line"><span>Receiving objects: 100% (142/142), 25.99 KiB | 0 bytes/s, done.</span></span>
<span class="line"><span>Resolving deltas: 100% (70/70), done.</span></span>
<span class="line"><span>Checking connectivity... done.</span></span></code></pre></div><p>一旦成功地克隆了仓库，你就可以像对待你电脑上任何其它目录那样浏览仓库中的文件。</p><p>另外一种获得仓库拷贝的方式是使用 web 界面。GitLab 和 GitHub 都会提供一个 .zip 格式的仓库快照文件。GitHub 有一个大大的绿色下载按钮，但是在 GitLab 中，可以在浏览器的右侧找到并不显眼的下载按钮。</p><p><img src="https://opensource.com/sites/default/files/1_gitlab-zip.jpg" alt=""></p><h3 id="仔细挑选" tabindex="-1">仔细挑选 <a class="header-anchor" href="#仔细挑选" aria-label="Permalink to “仔细挑选”">​</a></h3><p>另外一种从 Git 仓库中获取文件的方法是找到你想要的文件，然后把它从仓库中拽出来。只有 web 界面才提供这种方法，本质上来说，你看到的是别人的仓库克隆；你可以把它想象成一个 HTTP 共享目录。</p><p>使用这种方法的问题是，你也许会发现某些文件并不存在于原始仓库中，因为完整形式的文件可能只有在执行 make 命令后才能构建，那只有你下载了完整的仓库，阅读了 README 或者 INSTALL 文件，然后运行相关命令之后才会产生。不过，假如你确信文件存在，而你只想进入仓库，获取那个文件，然后离开的话，你就可以那样做。</p><p>在 GitLab 和 GitHub 中，单击文件链接，并在 Raw 模式下查看，然后使用你的 web 浏览器的保存功能，例如：在 Firefox 中，“文件” &gt; “保存页面为”。在一个 GitWeb 仓库中（这是一个某些更喜欢自己托管 git 的人使用的私有 git 仓库 web 查看器），Raw 查看链接在文件列表视图中。</p><p><img src="https://opensource.com/sites/default/files/1_webgit-file.jpg" alt=""></p><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h3><p>通常认为，和 Git 交互的正确方式是克隆完整的 Git 仓库。这样认为是有几个原因的。首先，可以使用 git pull 命令轻松地使克隆仓库保持更新，这样你就不必在每次文件改变时就重回 web 站点获得一份全新的拷贝。第二，你碰巧需要做些改进，只要保持仓库整洁，那么你可以非常轻松地向原来的作者提交所做的变更。</p><p>现在，可能是时候练习查找感兴趣的 Git 仓库，然后将它们克隆到你的硬盘中了。只要你了解使用终端的基础知识，那就不会太难做到。还不知道基本的终端使用方式吗？那再给多我 5 分钟时间吧。</p><h3 id="终端使用基础" tabindex="-1">终端使用基础 <a class="header-anchor" href="#终端使用基础" aria-label="Permalink to “终端使用基础”">​</a></h3><p>首先要知道的是，所有的文件都有一个路径。这是有道理的；如果我让你在常规的非终端环境下为我打开一个文件，你就要导航到文件在你硬盘的位置，并且直到你找到那个文件，你要浏览一大堆窗口。例如，你也许要点击你的家目录 &gt; 图片 &gt; InktoberSketches &gt; monkey.kra。</p><p>在那样的场景下，文件 monkeysketch.kra 的路径是：$HOME/图片/InktoberSketches/monkey.kra。</p><p>在终端中，除非你正在处理一些特殊的系统管理员任务，你的文件路径通常是以 $HOME 开头的（或者，如果你很懒，就使用 ~ 字符），后面紧跟着一些列的文件夹直到文件名自身。</p><p>这就和你在 GUI 中点击各种图标直到找到相关的文件或文件夹类似。</p><p>如果你想把 Git 仓库克隆到你的文档目录，那么你可以打开一个终端然后运行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://gitlab.com/foo/bar.git </span></span>
<span class="line"><span>$HOME/文档/bar.clone</span></span></code></pre></div><p>一旦克隆完成，你可以打开一个文件管理器窗口，导航到你的文档文件夹，然后你就会发现 bar.clone 目录正在等待着你访问。</p><p>如果你想要更高级点，你或许会在以后再次访问那个仓库，可以尝试使用 git pull 命令来查看项目有没有更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd $HOME/文档/bar.clone</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>bar.clone</span></span>
<span class="line"><span>$ git pull</span></span></code></pre></div><p>到目前为止，你需要初步了解的所有终端命令就是那些了，那就去探索吧。你实践得越多，Git 掌握得就越好（熟能生巧），这是重点，也是事情的本质。</p><hr>`,27)),s("p",null,[t[13]||(t[13]=i("via: ",-1)),n(a,{href:"https://opensource.com/life/16/7/stumbling-git"},{default:e(()=>[...t[12]||(t[12]=[i("https://opensource.com/life/16/7/stumbling-git",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=i("作者：",-1)),n(a,{href:"https://opensource.com/users/seth"},{default:e(()=>[...t[14]||(t[14]=[i("Seth Kenlon",-1)])]),_:1}),t[18]||(t[18]=i(" 译者：",-1)),n(a,{href:"https://github.com/chrisleegit"},{default:e(()=>[...t[15]||(t[15]=[i("ChrisLeeGit",-1)])]),_:1}),t[19]||(t[19]=i(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[16]||(t[16]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[20]||(t[20]=[i("LCTT",-1)])]),_:1}),t[23]||(t[23]=i(" 原创翻译，",-1)),n(a,{href:"https://linux.cn/"},{default:e(()=>[...t[21]||(t[21]=[i("Linux中国",-1)])]),_:1}),t[24]||(t[24]=i(" 荣誉推出",-1))])])}const C=p(g,[["render",b]]);export{y as __pageData,C as default};
